"""Chapter 2 Kinematics: written-answer questions, 5 per level."""
from .. import figs, sketches
from ..marker import Pitfall, Point
from .base import written

P = Point
PF = Pitfall


def _vt_trapezium():
    return figs.graph([(0, 0), (4, 12), (14, 12), (20, 0)], 20, 16, 4, 4, shade=None)


def _dt_three_sections():
    return figs.graph([(0, 0), (10, 40), (20, 40), (30, 70)], 30, 80, 5, 20, ylabel="distance / m")


# ---------------------------------------------------------------- L1
written("w2_define_speed", 2, 1, "2a",
        stem="Fig. 1 shows a car on a journey. Define average speed.",
        points=[P("total distance travelled ÷ total time taken", ["distance travelled divided by", "distance ÷ time", "distance / time", "distance over time", "distance travelled per unit time", "distance per unit time", "total distance divided by total time", "distance divided by the time"])],
        pitfalls=[PF(["displacement"], "Displacement per unit time is VELOCITY. Speed uses the distance travelled."),
                  PF(["time divided by distance", "time ÷ distance", "time / distance"], "Speed is distance DIVIDED BY time, not the other way round.")],
        model_answer="Average speed = total distance travelled ÷ total time taken.",
        hints=["Speed tells you how much distance is covered in each unit of time.",
               "Distance on top, time underneath.",
               "Write the definition as a sentence or an equation in words."],
        keywords="distance travelled ÷ time taken",
        figure=lambda: sketches.motion_sketch("start", "finish", "distance d in time t"),
        sample_pass=["Total distance travelled divided by the total time taken", "distance per unit time"],
        sample_fail=["Displacement divided by time", "Time taken divided by distance"])

written("w2_speed_vs_velocity", 2, 1, "2a",
        stem="State the difference between speed and velocity.",
        points=[P("velocity is speed in a stated direction (a vector); speed has no direction (a scalar)", ["direction", "vector", "scalar", "displacement"])],
        model_answer="Velocity is speed in a specified direction: velocity is a vector quantity (displacement per unit time), whereas speed is a scalar with magnitude only.",
        hints=["One of them tells you which way the object is going.",
               "Think about scalar and vector quantities.",
               "State which one includes direction."],
        keywords="velocity has direction (vector); speed does not (scalar)",
        sample_pass=["Velocity has a direction but speed does not", "speed is a scalar, velocity is a vector"],
        sample_fail=["Velocity is faster than speed", "They are the same thing"])

written("w2_define_acceleration", 2, 1, "2c",
        stem="Define acceleration and state its SI unit.",
        points=[P("rate of change of velocity: change in velocity ÷ time taken, in m/s²", ["change in velocity divided by", "change in velocity ÷", "change in velocity / time", "change in velocity per", "rate of change of velocity", "change of velocity over time", "velocity changes each second", "m/s²", "m/s^2", "m/s2", "metres per second squared", "metre per second squared"])],
        pitfalls=[PF(["change in distance", "rate of change of distance", "distance divided by time"], "Rate of change of distance is SPEED. Acceleration is the rate of change of VELOCITY.")],
        model_answer="Acceleration is the rate of change of velocity: change in velocity ÷ time taken. Its SI unit is the metre per second squared (m/s²).",
        hints=["Acceleration is about how quickly the velocity changes.",
               "Change in velocity on top, time underneath.",
               "Write the definition and the unit."],
        keywords="change in velocity ÷ time taken, m/s²",
        sample_pass=["The rate of change of velocity, measured in m/s²", "change in velocity divided by the time taken; unit m/s^2"],
        sample_fail=["Distance divided by time", "How fast something moves, in m/s"])

written("w2_gradient_dt", 2, 1, "2e",
        stem="Fig. 1 shows a distance–time graph. State what the gradient of a distance–time graph represents.",
        points=[P("the speed of the object", ["speed", "velocity", "how fast"])],
        pitfalls=[PF(["acceleration"], "The gradient of a DISTANCE–time graph is the speed. Acceleration is the gradient of a speed–time graph."),
                  PF(["represents the distance", "gives the distance", "shows the distance", "is the distance", "the distance travelled"], "Distance is read from the vertical axis; the GRADIENT gives the speed.")],
        model_answer="The gradient of a distance–time graph represents the speed of the object.",
        hints=["Gradient = change in the vertical quantity ÷ change in the horizontal quantity. What are the axes?",
               "Distance ÷ time gives which quantity?",
               "Name the quantity."],
        keywords="speed",
        figure=lambda: _dt_three_sections(),
        sample_pass=["The speed", "it gives the velocity of the object"],
        sample_fail=["The acceleration", "The distance travelled"])

written("w2_value_of_g", 2, 1, "2i",
        stem="State the acceleration of free fall near the Earth's surface, and what is assumed about air resistance.",
        points=[P("approximately 10 m/s², assuming air resistance is negligible (ignored)", ["10 m/s2", "10 m s-2", "10 ms-2", "ten metres per second squared", "10 metres per second squared", "9.8 m/s2", "9.81", "10 m/s per second", "10 m/s every second", "negligible", "ignored", "no air resistance", "without air resistance", "neglect"])],
        model_answer="About 10 m/s² (more precisely 9.8 m/s²), assuming air resistance is negligible.",
        hints=["Every second of free fall adds about the same amount to the speed. How much?",
               "The value only applies if one force is ignored. Which?",
               "Give the value with its unit and the assumption."],
        keywords="10 m/s², air resistance negligible",
        sample_pass=["About 10 m/s² if air resistance is negligible", "9.8 m/s^2 with no air resistance"],
        sample_fail=["10 m/s", "It depends on the mass"])

# ---------------------------------------------------------------- L2
written("w2_dt_shapes", 2, 2, "2f",
        stem="Fig. 1 shows a distance–time graph with three sections. Describe the motion in each of the three sections.",
        points=[P("first section: straight sloping line, so uniform (constant) speed", ["constant speed", "uniform speed", "steady speed", "straight line"]),
                P("second section: horizontal line, so the object is at rest (stationary)", ["at rest", "stationary", "not moving", "stopped", "horizontal"]),
                P("third section: straight line steeper than the first, so constant speed but faster", ["faster", "greater speed", "higher speed", "steeper", "quicker", "larger gradient"])],
        min_points=2,
        model_answer="In the first section the line is straight and sloping, so the object moves at a constant speed. In the second section the line is horizontal, so the distance is not changing and the object is at rest. In the third section the line is straight but steeper, so the object moves at a constant speed greater than before.",
        hints=["The gradient of a distance–time graph is the speed. Look at the gradient of each section.",
               "Flat means zero gradient; steeper means a bigger gradient.",
               "Describe the speed in each of the three sections."],
        keywords="constant speed; at rest; constant higher speed",
        figure=lambda: _dt_three_sections(),
        sample_pass=["Constant speed, then stationary, then constant speed but faster", "first it moves at a steady speed, then it stops, then it moves again with a greater speed"],
        sample_fail=["It accelerates, then decelerates, then accelerates", "It goes up, flat, then up"])

written("w2_vt_horizontal", 2, 2, "2g",
        stem="Fig. 1 shows a speed–time graph. Describe the motion represented by the horizontal section, and explain how you can tell.",
        points=[P("constant (uniform) speed", ["constant speed", "uniform speed", "steady speed", "same speed", "speed does not change"]),
                P("because the gradient is zero, so the acceleration is zero", ["gradient is zero", "zero gradient", "no gradient", "acceleration is zero", "zero acceleration", "no acceleration", "not accelerating", "speed is not changing", "flat", "horizontal means"])],
        pitfalls=[PF(["at rest", "stationary", "not moving"], "On a SPEED–time graph a horizontal line means constant speed, not rest. The speed is not zero.")],
        model_answer="The horizontal section represents motion at a constant speed. The gradient of a speed–time graph is the acceleration; a horizontal line has zero gradient, so the acceleration is zero and the speed is unchanging.",
        hints=["Careful: this is a SPEED–time graph. What does a horizontal line mean for the speed?",
               "What is the gradient of a horizontal line, and what does the gradient represent here?",
               "Describe the motion and give the reason from the gradient."],
        keywords="constant speed, zero gradient = zero acceleration",
        figure=lambda: _vt_trapezium(),
        sample_pass=["The object moves at a constant speed because the gradient, which is the acceleration, is zero", "steady speed; the line is flat so there is no acceleration"],
        sample_fail=["The object is at rest", "The object is slowing down"])

written("w2_area_under_vt", 2, 2, "2h",
        stem="Fig. 1 shows a speed–time graph. State what the area under a speed–time graph represents, and explain why.",
        points=[P("the distance travelled", ["distance travelled", "distance", "displacement"]),
                P("because area = speed × time (height × width), and speed × time = distance", ["speed × time", "speed times time", "height × width", "speed multiplied by time", "m/s × s", "units of metres"])],
        model_answer="The area under a speed–time graph represents the distance travelled, because the area is found by multiplying speed (the height) by time (the width), and speed × time = distance.",
        hints=["Think about the units: what do you get when you multiply the vertical axis unit by the horizontal axis unit?",
               "m/s × s = m. Which quantity is measured in metres?",
               "Name the quantity and explain with speed × time."],
        keywords="distance travelled, speed × time",
        figure=lambda: _vt_trapezium(),
        sample_pass=["The distance travelled, because speed multiplied by time gives distance", "distance: height × width is speed × time"],
        sample_fail=["The acceleration", "The average speed"])

written("w2_uniform_vs_nonuniform", 2, 2, "2d",
        stem="Explain the difference between uniform acceleration and non-uniform acceleration, and describe how each appears on a speed–time graph.",
        points=[P("uniform acceleration: the velocity changes by the same amount every second (constant acceleration), shown by a straight sloping line", ["same amount every second", "constant acceleration", "changes steadily", "equal amounts", "straight line", "straight sloping"]),
                P("non-uniform acceleration: the velocity changes by different amounts each second (acceleration changing), shown by a curved line", ["different amounts", "changing acceleration", "not constant", "varies", "curve", "curved line"])],
        model_answer="Uniform acceleration means the velocity changes by the same amount in each second, so the acceleration is constant and the speed–time graph is a straight sloping line. Non-uniform acceleration means the velocity changes by different amounts in each second, so the acceleration itself is changing and the speed–time graph is a curve.",
        hints=["Acceleration is the gradient of a speed–time graph. What does a constant gradient look like? A changing one?",
               "Straight line versus curve.",
               "Explain both types and their graph shapes."],
        keywords="uniform: same change each second, straight line; non-uniform: changing, curve",
        sample_pass=["Uniform acceleration changes the velocity by the same amount each second and gives a straight line; non-uniform gives a curve because the acceleration changes",
                     "constant acceleration is a straight sloping line, changing acceleration is a curve"],
        sample_fail=["Uniform acceleration is faster", "Both are straight lines"])

