# ---------------------------------------------------------------- L3
written("w2_lift_vt_graph", 2, 3, "2g",
        stem="Fig. 1 shows the speed–time graph of a lift travelling between two floors. Describe the motion of the lift in each stage and explain how you could find the total distance travelled.",
        points=[P("first stage: speed increases steadily from rest, uniform acceleration", ["accelerat", "speeds up", "speed increases", "from rest"]),
                P("middle stage: constant speed; final stage: speed decreases steadily to rest, uniform deceleration", ["constant speed", "steady speed", "decelerat", "slows down", "comes to rest", "speed decreases"]),
                P("total distance = area under the whole graph (trapezium or sum of the shapes)", ["area under", "area of the trapezium", "area", "triangle and rectangle", "sum of the areas"])],
        min_points=2,
        model_answer="The lift first accelerates uniformly from rest (straight line rising), then travels at a constant speed (horizontal line), then decelerates uniformly to rest (straight line falling). The total distance travelled is the area under the whole graph, found from the trapezium or by adding the two triangles and the rectangle.",
        hints=["Look at the three sections: rising, flat, falling. What does each mean for the speed?",
               "Distance is the area under a speed–time graph.",
               "Describe each stage and state how to find the distance."],
        keywords="accelerates, constant speed, decelerates; distance = area under graph",
        figure=lambda: _vt_trapezium(),
        sample_pass=["It accelerates uniformly, then moves at constant speed, then decelerates to rest; the distance is the area under the graph",
                     "speeds up, steady speed, slows down; find the area of the trapezium for the distance"],
        sample_fail=["The lift goes up, stays still, then comes down", "The distance is the height of the graph"])

written("w2_ball_up_down", 2, 3, "2c",
        stem="A ball is thrown vertically upwards. Describe its velocity and acceleration as it rises, at the top, and as it falls (ignore air resistance).",
        points=[P("rising: velocity decreases (decelerates) while the acceleration is 10 m/s² downwards", ["slows", "decelerat", "velocity decreases", "speed decreases", "loses speed"]),
                P("at the top: velocity is momentarily zero but the acceleration is still 10 m/s² downwards (not zero)", ["zero velocity", "velocity is zero", "momentarily zero", "stops momentarily", "acceleration is still", "acceleration is not zero", "still 10"]),
                P("falling: velocity increases downwards; the acceleration is constant at 10 m/s² downwards throughout", ["speeds up", "velocity increases", "accelerates downwards", "constant acceleration", "10 m/s", "same acceleration throughout", "always downwards"])],
        min_points=2,
        pitfalls=[PF(["acceleration is zero at the top", "zero acceleration at the top", "no acceleration at the top"], "At the top the VELOCITY is zero, but gravity still acts, so the acceleration is still 10 m/s² downwards.")],
        model_answer="As the ball rises its velocity decreases, because gravity gives it an acceleration of 10 m/s² downwards. At the highest point its velocity is momentarily zero, but the acceleration is still 10 m/s² downwards. As it falls its velocity increases downwards. The acceleration is constant at 10 m/s² downwards throughout the motion.",
        hints=["Only gravity acts, so what is the acceleration at every moment, including the top?",
               "Separate velocity (which changes) from acceleration (which does not).",
               "Describe the velocity in each stage and state the acceleration throughout."],
        keywords="velocity decreases, zero at top, increases falling; acceleration constant 10 m/s² downwards",
        sample_pass=["Going up it slows down, at the top the velocity is zero but the acceleration is still 10 m/s² down, then it speeds up as it falls",
                     "the velocity decreases, is momentarily zero, then increases downwards; the acceleration is 10 m/s² downwards the whole time"],
        sample_fail=["At the top both velocity and acceleration are zero", "The acceleration changes direction at the top"])

